```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy "auctions_select_authenticated"
  on public.auctions for select
  to authenticated
  using (true);

create policy "bids_select_authenticated"
  on public.bids for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_seller_id uuid;
  v_highest_bid numeric;
  v_min_increment numeric;
  v_ends_at timestamptz;
begin
  if auth.role() is distinct from 'authenticated' then
    raise exception 'Not authenticated';
  end if;

  select
    seller_id,
    highest_bid,
    min_increment,
    ends_at
  into
    v_seller_id,
    v_highest_bid,
    v_min_increment,
    v_ends_at
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if now() > v_ends_at then
    raise exception 'Auction has ended';
  end if;

  if auth.uid() = v_seller_id then
    raise exception 'Seller cannot bid on own auction';
  end if;

  if p_amount < v_starting_price then
    raise exception 'Bid is below starting price';
  end if;

  if v_highest_bid is null then
    if p_amount < v_starting_price then
      raise exception 'Bid is below starting price';
    end if;
  else
    if p_amount < v_highest_bid + v_min_increment then
      raise exception 'Bid is below highest bid plus minimum increment';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, auth.uid(), p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
end
$$;
```

