create policy "Auctions are readable by authenticated users"
  on public.auctions for select
  to authenticated
  using (true);

create policy "Bids are readable by the bidder or the auction seller"
  on public.bids for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_highest numeric;
  v_auction public.auctions%rowtype;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'unknown auction';
  end if;

  if v_auction.seller_id = v_user then
    raise exception 'cannot bid on your own auction';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid must be at least the starting price';
    end if;
    v_highest := p_amount;
  else
    if p_amount < v_auction.highest_bid + v_auction.min_increment then
      raise exception 'bid must be at least the highest bid plus the minimum increment';
    end if;
    v_highest := p_amount;
  end if;

  update public.auctions
  set highest_bid = v_highest,
      highest_bidder = v_user
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_user, p_amount);

  return v_highest;
end
$$;
