create function private.is_instructor(p_class_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.classes c where c.id = p_class_id and c.instructor_id = auth.uid())
$$;

create function private.class_has_room(p_class_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select (select count(*) from public.class_spots s where s.class_id = p_class_id and s.status = 'enrolled') < (
    select c.capacity from public.classes c where c.id = p_class_id
  )
$$;

alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create policy "classes_select_authenticated"
  on public.classes for select to authenticated
  using (true);

create policy "class_spots_select_authenticated"
  on public.class_spots for select to authenticated
  using (
    user_id = auth.uid()
    or private.is_instructor(class_id)
  );

create policy "class_spots_insert_member"
  on public.class_spots for insert to authenticated
  with check (
    user_id = auth.uid()
    and status in ('enrolled', 'waitlisted')
    and (
      status = 'enrolled'
      and private.class_has_room(class_id)
      or status = 'waitlisted'
    )
  );

create policy "class_spots_update_waitlisted_to_enrolled"
  on public.class_spots for update to authenticated
  using (user_id = auth.uid() and status = 'waitlisted')
  with check (
    user_id = auth.uid()
    and status = 'enrolled'
    and private.class_has_room(class_id)
  );

create policy "class_spots_delete_member"
  on public.class_spots for delete to authenticated
  using (user_id = auth.uid());

create policy "class_spots_instructor_delete"
  on public.class_spots for delete to authenticated
  using (private.is_instructor(class_id));
